import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_0: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.500-toads","name":"500 Toads","kind":"SPELL","rank":1,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure hundreds of magical toads to fill the area and hop around. The vast quantity of hopping toads provides enough weight and height for the creatures to trigger any potential trap in the area that could be triggered by the weight, movement, or position of a Medium creature. The area is difficult terrain, and the magic reconstructs any toads destroyed by traps to keep the area full of toads for the duration of the spell.","source":{"provider":"PAIZO","sourceId":"w7BHU5rk5JKuIRCe","book":"Pathfinder NPC Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.acid-splash","name":"Acid Splash","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["acid","attack","cantrip","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false},{"id":"gcovwqxwitqchoin","formula":"1","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You splash a glob of acid that splatters your target and nearby creatures. Make a spell attack. If you hit, you deal 1d6 acid damage plus 1 splash acid damage. On a critical success, the target also takes (ceil(@item.level/2))[persistent,acid] damage.\nHeightened (3rd) The initial damage increases to 2d6, and the persistent damage increases to 2.\n\nHeightened (5th) The initial damage increases to 3d6, the persistent damage increases to 3, and the splash damage increases to 2.\n\nHeightened (7th) The initial damage increases to 4d6, the persistent damage increases to 4, and the splash damage increases to 3.\n\nHeightened (9th) The initial damage increases to 5d6, the persistent damage increases to 5, and the splash damage increases to 4.","source":{"provider":"PAIZO","sourceId":"gISYsBFby1TiXfBt","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.acidic-burst","name":"Acidic Burst","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["acid","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You create a shell of acid around yourself that immediately bursts outward, dealing 2d6 acid damage to each creature in the area with a basic Reflex save.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"rnNGALRtsjspFTws","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.adapt-self","name":"Adapt Self","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cleric","concentrate","focus","manipulate","morph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You make subtle changes to your body to adapt to the situation. Choose one of the following options that applies to you.\n- If you are in water, you gain a swim Speed equal to half your Speed.\n\n- If you are in water, you become able to breathe water.\n\n- If it's too dark for you to see, you gain darkvision.\n\n- If you are in an environment of severe heat or severe cold, you are protected from the effects of severe heat or severe cold, and the spell lasts 10 minutes.","source":{"provider":"PAIZO","sourceId":"GUnw9YXaW3YyaCAU","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.admonishing-ray","name":"Admonishing Ray","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","concentrate","manipulate","nonlethal"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"A ray of energy bludgeons your target into submission without causing lasting harm. When you cast this spell, you choose whether the ray feels like a strong punch or slap. Make a spell attack roll. The ray deals 2d6 bludgeoning damage.\n\nCritical Success The target takes double damage.\n\nSuccess The target takes full damage.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"uToa7ksKAzmEpkKC","book":"Pathfinder #158: Sixty Feet Under","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.agile-feet","name":"Agile Feet","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of the current turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The blessings of your god make your feet faster and your movements more fluid. You gain a +5-foot status bonus to your Speed and ignore difficult terrain. As part of casting agile feet, you can Stride, Step, or ; you can instead Burrow, Climb, Fly, or Swim if you have the appropriate Speed.","source":{"provider":"PAIZO","sourceId":"cOjlzWerBwbPWVkX","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.agitate","name":"Agitate","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","mental","nonlethal"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"2d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d8"}},"counteraction":false,"ritual":null,"description":"You send the target's mind and body into overdrive, forcing it to become restless and hyperactive. During the duration, the target must Stride, Fly, or Swim at least once each turn or take 2d8 mental damage at the end of its turn. The GM might decide to add additional move actions to the list for creatures that possess only a more unusual form of movement. The duration of this effect depends on the target's Will save.\nCritical Success The spell has no effect.\n\nSuccess The duration is 1 round.\n\nFailure The duration is 2 rounds.\n\nCritical Failure The duration is 4 rounds.\nHeightened (+1) The damage increases by 2d8.","source":{"provider":"PAIZO","sourceId":"r8g7oSumKOHDqJsd","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.air-bubble","name":"Air Bubble","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","concentrate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature within range enters an environment where it can't breathe.\n\nA bubble of pure air appears around the target's head, allowing it to breathe normally. The effect ends as soon as the target returns to an environment where it can breathe normally.","source":{"provider":"PAIZO","sourceId":"W69zswpj0Trdy5rj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.airburst","name":"Airburst","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["air","concentrate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"target":"all creatures and unattended objects","area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A blast of wind wildly pushes everything nearby. Unattended objects of 1 Bulk or less are pushed 5 feet away from you. Large or smaller creatures must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes a -2 status penalty to checks made during its reactions until the end of your turn.\n\nFailure As success, and the creature is pushed 5 feet away from you.\n\nCritical Failure The creature is pushed 5 feet away from you and can't use reactions until the end of your turn.\n\nHeightened (4th) Increase the area to a 10-foot emanation and increase the distance objects and creatures are pushed to 10 feet.","source":{"provider":"PAIZO","sourceId":"fprqWKUc0jnMIyGU","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.alarm","name":"Alarm","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"BURST","feet":20}},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward an area to alert you when creatures enter without your permission. When you cast alarm, select a password. Whenever a Small or larger corporeal creature enters the spell's area without speaking the password, alarm sends your choice of a mental alert (in which case the spell gains the mental trait) or an audible alarm with the sound and volume of a hand bell (in which case the spell gains the auditory trait). Either option automatically awakens you, and the bell allows each creature in the area to attempt a perception check to wake up. A creature aware of the alarm must succeed at a Stealth check against the spell's DC or trigger the spell when moving into the area.\n\nHeightened (3rd) You can specify a trigger for which types of creatures sound the alarm spell.","source":{"provider":"PAIZO","sourceId":"4WAib3GichxLjp5p","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.all-encompassing-hunger","name":"All-Encompassing Hunger","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["death","focus","manipulate","void","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"Q5pYqnYJKLLFbsHX","formula":"1d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Q5pYqnYJKLLFbsHX":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You reach out to devour a life, regardless of whether you need it for sustenance. The target takes 1d6 void damage, with a basic Fortitude save. If the creature is reduced to 0 Hit Points, it dies, and you gain temporary Hit Points equal to the damage dealt. These temporary Hit Points last for 1 minute.\nHeightened (+1) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"wJi0lq4yA5Mlj0MY","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ancestral-memories","name":"Ancestral Memories","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The memories of long-dead spellcasters grant you their knowledge, making your spells more formidable. You gain either a +1 status bonus to the next spell attack roll you attempt before the end of your turn or an enemy within 60 feet takes a –1 status penalty to the next saving throw they attempt against a spell you cast before the end of your turn.\nHeightened (5th) The bonus increases to +2 or the penalty increases to –2.\n\nHeightened (8th) The bonus increases to +3 or the penalty increases to –3","source":{"provider":"PAIZO","sourceId":"dtOUkMC57izf93z5","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ancestral-touch","name":"Ancestral Touch","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["emotion","fear","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"2d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You touch a creature and force them to see and feel the ancestors surrounding you. The target takes 2d4 mental damage, with results depending on a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target is Frightened 1 and takes full damage.\n\nCritical Failure The target is Frightened 2 and takes double damage.\nHeightened (+1) The mental damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"d2pi7laQkzlr3wrS","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ancient-dust","name":"Ancient Dust","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","void"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"2voY0xl4sJrjuqKs","formula":"1","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false},{"id":"bmKxkM6C7wpQlsxf","formula":"0","damageType":"void","kind":"DAMAGE","applyAbilityModifier":true}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"2voY0xl4sJrjuqKs":"1","bmKxkM6C7wpQlsxf":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You cough up a cloud of gray soil, echoing the dust in the graves of Kemnebi's many victims. Each creature in the area takes void damage equal to your spellcasting modifier and 1 persistent void damage depending on its Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and no persistent damage.\n\nFailure The creature takes full damage and persistent damage.\n\nCritical Failure The creature takes double damage and double the persistent damage.\n\nHeightened (+2) The initial void damage increases by 1d6, and the persistent damage increases by 1.","source":{"provider":"PAIZO","sourceId":"OJ91rm1FkJSlf3nk","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.angelic-halo","name":"Angelic Halo","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["aura","concentrate","focus","holy","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain an angelic halo with an aura that increases allies' healing from the spell. Allies in your halo's emanation who are healed by a heal spell gain a status bonus to Hit Points regained equal to double the heal spell's rank.","source":{"provider":"PAIZO","sourceId":"w3uGXDVEdbLFZVO0","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.angelic-messenger","name":"Angelic Messenger","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert; you must be an angel)","secondaryCasters":0},"description":"You transport yourself to either a celestial plane or a world in the Universe where worshippers of your patron can be found. You must be of no higher level than double angelic messenger's spell rank.\n\nCritical Success As success, but if you've never visited that plane or world before, you appear right in front of the message's intended recipient.\n\nSuccess You arrive on the target plane or world at the last location you visited on that plane or world, or to a random location within [[/r 10d10 #Miles Off]] miles of your message's intended recipient if you've never visited that plane or world before.\n\nFailure You don't travel.\n\nCritical Failure You accidentally travel to the wrong plane, possibly a dangerous plane.","source":{"provider":"PAIZO","sourceId":"joEruBVz31Uxczzq","book":"Pathfinder Monster Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animal-allies","name":"Animal Allies","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"3d4"}},"counteraction":false,"ritual":null,"description":"You summon tiny, ordinary animals from the environment, such as insects, birds, or fish, to quickly lash out at nearby foes. The animals swarm around the creatures in the area, dealing each of them 3d4 piercing damage with a basic Reflex save.\n\nHeightened (+1) The damage increases by 3d4","source":{"provider":"PAIZO","sourceId":"Aap7nGpC7neTWm78","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.animate-rope","name":"Animate Rope","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"up to 50 feet of rope or a nonliving rope-like object","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You cause a length or section of or a rope-like object to animate and follow simple commands. You can give it two commands when you Cast the Spell, and one command each time you Sustain the Spell.\n\n- Bind (attack) The Rope attempts to partially bind a creature. Attempt a spell attack roll against the target's Reflex DC. If you succeed, the target takes a –10-foot circumstance penalty to its Speed (-20-foot on a critical success). This ends if the target Escapes against your spell DC or breaks the Rope. (A standard adventuring Rope has Hardness 2, HP 8, and a Broken Threshold of 4.)\n\n- Coil The Rope forms a tidy, coiled stack.\n\n- Crawl The Rope inches along the ground like a snake, moving one of its ends 10 feet. The Rope must move along a surface, but that surface doesn't need to be horizontal.\n\n- Knot The Rope ties a sturdy knot in itself.\n\n- Loop The Rope forms a simple loop at one or both ends, or straightens itself back out.\n\n- Tie The Rope ties itself around a willing creature or an object that's unattended or attended by a willing creature.\n\n- Undo The Rope undoes one of its knots, ties, or bindings.\n\nHeightened (+2) The range increases by 50 feet, and you can animate 50 more feet of Rope.","source":{"provider":"PAIZO","sourceId":"rVANhQgB8Uqi9PTl","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ant-haul","name":"Ant Haul","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You reinforce the target's musculoskeletal system to bear more weight. The target can carry 3 more Bulk than normal before becoming and up to a maximum of 6 more Bulk.","source":{"provider":"PAIZO","sourceId":"X9dkmh23lFwMjrYd","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.anticipate-peril","name":"Anticipate Peril","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You grant the target brief foresight. The target gains a +1 status bonus to its next initiative roll, after which the spell ends.\n\nHeightened (+2) The status bonus increases by 1, to a maximum of +4 at 7th rank.","source":{"provider":"PAIZO","sourceId":"EUMjrJJwSgsqNidi","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.appearance-of-wealth","name":"Appearance of Wealth","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","illusion","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a brief vision of immense wealth filling the spell's area. Each creature within 20 feet of the area that could be enticed by material wealth must attempt a Will saving throw. A creature that enters the area automatically disbelieves the illusion, and disbelieving the illusion ends any condition imposed by the spell. As long as you Sustain the Spell, other creatures react to the treasure like they would any other illusion, but they are not at risk of becoming Fascinated.\n\nCritical Success The creature disbelieves the illusion and is unaffected by it.\n\nSuccess The creature is Fascinated by the wealth until it has completed its first action on its next turn.\n\nFailure The creature is Fascinated by the illusion.","source":{"provider":"PAIZO","sourceId":"ZeftDoh0nFAXBAWY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.approximate","name":"Approximate","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","detection","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Area 1 cubic foot\n\nYour magic quickly flows over an area to help you count and catalog. Name a particular type of object you are looking for within the area. You gain an instant estimate of the quantity of the chosen objects that are clearly visible within the target area. The number is rounded to the largest digit. For example, you could look at a pile of 180 copper coins, and you would learn that it held about 200 coins, but you couldn't determine there were exactly 180 coins.\n\nThe type of object you name can be as specific or general as you like-\"dented copper coins\" is as viable as \"coins\"-but the distinguishing features must be obvious at a glance, and the spell is automatically fooled by objects disguised as other objects. For instance, the spell would register copper coins plated in gold as gold coins, not copper coins","source":{"provider":"PAIZO","sourceId":"EqdSKqr8Qj5TUhMR","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aqueous-blast","name":"Aqueous Blast","kind":"SPELL","rank":1,"rarity":"RARE","traits":["attack","manipulate","water"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of your turn","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"LWLaBwdvEpvNhrrl","formula":"2d8","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"LWLaBwdvEpvNhrrl":"1d8"}},"counteraction":false,"ritual":null,"description":"You evoke a mass of water into the air around your outstretched fist. For the remainder of your turn, you can blast targets within 30 feet with this water by spending a single action which has the attack and concentrate traits. When you do so, attempt a ranged spell attack roll. If you hit, you inflict 2d8 bludgeoning damage. On a critical hit, the blast knocks the target .\n\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"6wLY5LnehCo3tHlr","book":"Pathfinder Kingmaker","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.armor-of-thorn-and-claw","name":"Armor of Thorn and Claw","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate","morph"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"hY0fBGsbaFD86ct0","formula":"1","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"hY0fBGsbaFD86ct0":"2"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Razor-sharp thorns and claws erupt from your skin or scales. Whenever a creature touches you or hits you with a melee unarmed attack, it takes 1 piercing damage. Additionally, if you become , , or otherwise held in a creature's grasp, such as by being engulfed or swallowed, the creature takes (ceil(@item.rank / 2))d4[persistent,bleed] damage.\nHeightened (+2) The piercing damage increases by 2, and the persistent bleed damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"EPTmSiURVp2ldkVB","book":"Pathfinder Lost Omens Draconic Codex","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.arms-of-nature","name":"Arms of Nature","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","wood"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 wooden object or plant of at least 4 Bulk","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"All wood, dead or alive, is your armory. When you cast this spell, you draw forth a +1 weapon of your choice from the target. The weapon must be 2 Bulk or less. This weapon is of the same material as the target.\nHeightened (3rd) The weapon is a +1 striking weapon.\n\nHeightened (5th) The weapon is a +2 striking weapon.\n\nHeightened (7th) The weapon is a +3 greater striking weapon.","source":{"provider":"PAIZO","sourceId":"aHu20NHj7YIqxr80","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.ashen-wind","name":"Ashen Wind","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a swirling wind of ashes that blows through the area. Each creature in the area must attempt a Fortitude save or get the cloying ash in its lungs.\n\nSuccess The creature is unaffected.\n\nFailure The creature is Sickened 1.\n\nCritical Failure The creature is Sickened 2.","source":{"provider":"PAIZO","sourceId":"NtzNCW32UlPdY2xS","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.athletic-rush","name":"Athletic Rush","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your body fills with physical power and skill. You gain a +10-foot status bonus to Speed and a +2 status bonus to Athletics checks. As a part of Casting this Spell, you can use a Stride, Leap, Climb, or Swim action. The spell's bonuses apply during that action.","source":{"provider":"PAIZO","sourceId":"UGJzJRJDoonfWqqI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.augmented-body","name":"Augmented Body","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","morph","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You magically augment your body with clockwork parts and magitech innovations. Choose any one effect of your choice. You can Dismiss the spell.\n- Ablative Plating You coat your body with metal plates that protect your vital organs. You gain resistance 1 to physical damage.\n- Clockwork Arm You transform one of your arms into a clockwork arm powered by gears, springs, and pneumatic actuators. You gain a clockwork fist unarmed attack, which has the agile, finesse, and free-hand traits and deals 1d6 bludgeoning damage.\n- Spined Fingertips Your fingers sprout microscopic metal spines that enable you to cling to surfaces like a spider. You gain a climb Speed of 20 feet.\n- Spring-Loaded Legs Your leg muscles are augmented with powerful springs. You gain a +10-foot status bonus to your Speed and double the distance you .\n\nHeightened (3rd) The ablative plating's resistance increases to 2. The clockwork fist is a +1 striking weapon.\n\nHeightened (5th) The ablative plating's resistance increases to 3, and the clockwork fist is a +2 striking weapon.\n\nHeightened (7th) The ablative plating's resistance increases to 4, and the clockwork fist is a +2 greater striking weapon.\n\nHeightened (9th) The ablative plating's resistance increases to 5 and the clockwork fist is a +3 major striking weapon.","source":{"provider":"PAIZO","sourceId":"pSepsfCrrAKuwA0N","book":"Pathfinder #215: To Blot Out the Sun","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bane","name":"Bane","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["aura","concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"enemies in the area","area":{"shape":"EMANATION","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You fill the minds of your enemies with doubt. Enemies in the area must succeed at a Will save or take a –1 status penalty to attack rolls as long as they are in the area. Once per round on subsequent turns, you can Sustain the spell to increase the emanation's radius by 10 feet and force enemies in the area that weren't yet affected to attempt another saving throw.\n\nBane can counteract .","source":{"provider":"PAIZO","sourceId":"7ZinJNzxq0XF0oMx","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.barbed-spear","name":"Barbed Spear","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"iYksIgGrnndrtLnp","formula":"1d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"iYksIgGrnndrtLnp":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You conjure a vicious barbed spear and hurl it at a foe. Make a ranged spell attack roll, dealing 1d8 piercing damage on a success and double damage on a critical success. The spear remains lodged within a creature it hits, making the target Clumsy 1 (or increasing its clumsy condition by 1 if it is already clumsy) for 1 minute or until the spear is removed with a successful Athletics check against your spell DC as an Interact action, whichever comes first.\nHeightened (+1) The initial damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"dQ7LrD2HxJoCzi2M","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.befuddle","name":"Befuddle","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sow seeds of confusion in your target's mind, causing its actions and thoughts to become clumsy.\nCritical Success The target is unaffected.\n\nSuccess The target is Clumsy 1 and Stupefied 1.\n\nFailure The target is Clumsy 2 and Stupefied 2.\n\nCritical Failure The target is Clumsy 3, Stupefied 3, and .","source":{"provider":"PAIZO","sourceId":"pBevG6bSQOiyflev","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.benediction","name":"Benediction","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["aura","concentrate","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Divine protection helps protect your companions. You and your allies gain a +1 status bonus to AC while within the emanation. Once per round on subsequent turns, you can Sustain the spell to increase the emanation's radius by 10 feet.\n\nBenediction can counteract malediction.","source":{"provider":"PAIZO","sourceId":"HGSCofGACf1TVH55","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.beseech-the-sphinx","name":"Beseech the Sphinx","kind":"SPELL","rank":1,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature other than yourself","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You look to the great Sphinx constellation, wisest of all cosmic guides and favored of Phimater, asking them to lend their insight to the target. Choose one skill and one type of saving throw (Fortitude, Reflex, or Will). The target gains a +1 status bonus to those skill checks and saving throws for the duration.\nHeightened (4th) The status bonus increases to +2.\n\nHeightened (7th) The status bonus increases to +3.","source":{"provider":"PAIZO","sourceId":"7GZVTtzN7H4Jujc1","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bit-of-luck","name":"Bit of Luck","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","fortune","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tilt the scales of luck slightly to protect a creature from disaster. When the target would attempt a saving throw, it can roll twice and use the better result. Once it does this, the spell ends.\n\nIf you cast bit of luck again, any previous bit of luck you cast that's still in effect ends. After a creature has been targeted with bit of luck, it becomes temporarily immune for 24 hours.","source":{"provider":"PAIZO","sourceId":"Fr2CGvWcgSyLcUi7","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.biting-words","name":"Biting Words","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","auditory","concentrate","linguistic","manipulate","sonic"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You entwine magic with your voice, causing your taunts and jibes to physically harm your enemies. You can attack with your words once when you finish Casting the Spell, and can repeat the attack once on each of your subsequent turns by taking a single action, which has the attack, concentrate, and linguistic traits. After your third attack total, the spell ends.\n\nWhen you attack with biting words, make a ranged spell attack roll against a creature within 30 feet, dealing 2d6 sonic damage if you hit (or double damage on a critical hit).\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"yafsV0ni7rFgqJBj","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bless","name":"Bless","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["aura","concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"you and allies in the area","area":{"shape":"EMANATION","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"Blessings from beyond help your companions strike true. You and your allies gain a +1 status bonus to attack rolls while within the emanation. Once per round on subsequent turns, you can Sustain the spell to increase the emanation's radius by 10 feet.\n\nBless can counteract .","source":{"provider":"PAIZO","sourceId":"XSujb7EsSwKl19Uu","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blood-ward","name":"Blood Ward","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron's aegis descends to shield a target from harm. Designate one of the following creature traits: aberration, animal, beast, celestial, construct, dragon, elemental, fey, fiend, fungus, monitor, ooze, plant, or undead. The target gains a +1 status bonus to its saving throws and AC against creatures with that trait.\n\nHeightened (5th) The status bonus increases to +2.","source":{"provider":"PAIZO","sourceId":"dFejDNEmVj3CwYLL","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.boost-eidolon","name":"Boost Eidolon","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","summoner"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"your eidolon","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus deeply on the link between you and your eidolon and boost the power of your eidolon's attacks. Your eidolon gains a +2 status bonus to damage rolls with its unarmed attacks. If your eidolon's Strikes deal more than one weapon damage die, the status bonus increases to 2 per weapon damage die, to a maximum of +8 with four weapon damage dice.","source":{"provider":"PAIZO","sourceId":"HStu2Yhw3iQER9tY","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.brain-drain","name":"Brain Drain","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You probe the target's mind to glean knowledge. This deals 1d8 mental damage with a basic Will save.\n\nIf the target fails the save, you sort through the stolen memories to attempt a single check to . Choose a skill that has the Recall Knowledge action, and use the target's skill modifier for the check.\n\nHeightened (+1) The mental damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"k2QrUk7jWMAWozMh","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bramble-bush","name":"Bramble Bush","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"CUBE","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"t5QwR29amSZkE1Dd","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"t5QwR29amSZkE1Dd":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"In a sudden burst of growth, you cause a thorned bush to sprout from the ground, lash around, and wither. Any creature in the area takes 1d4 piercing damage with a basic Reflex saving throw.\n\nUntil the start of your next turn, the area is difficult terrain and hazardous terrain. Any creature entering the square takes (1d4 + ceil(@item.level / 2) - 1)[piercing] damage with a basic Reflex saving throw.\nHeightened (+2) The initial damage increases by 1d4, and the damage dealt by hazardous terrain increases by 1.","source":{"provider":"PAIZO","sourceId":"mAdxOQUA2cHgKViU","book":"Pathfinder #203: Shepherd of Decay","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.breadcrumbs","name":"Breadcrumbs","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You protect your target from going astray in hostile territory by tracking where it's already been, helping it deduce where it still needs to go. The target leaves a glittering trail behind it that lasts for the spell's duration. This trail doesn't denote the direction or the order of its path-it merely indicates where the target has moved during the spell's duration.\n\nHeightened (2nd) The duration increases to 8 hours.\n\nHeightened (3rd) The duration increases to last until your next daily preparations.","source":{"provider":"PAIZO","sourceId":"PGVhjDbzC4lf6aXF","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.breathe-fire","name":"Breathe Fire","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"A gout of flame sprays from your mouth. You deal 2d6 fire damage to creatures in the area with a basic Reflex save.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"y6rAdMK6EFlV6U0t","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.briny-bolt","name":"Briny Bolt","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"YLzufF5UKRGjT83M","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"YLzufF5UKRGjT83M":"2d6"}},"counteraction":false,"ritual":null,"description":"You hurl a bolt of saltwater from your extended hand. Make a ranged spell attack against a target within range.\n\nCritical Success The creature takes 4d6 bludgeoning damage and is for 1 round and for 1 minute as saltwater sprays into its eyes. The creature can spend an Interact action to rub its eyes and end the blinded condition, but not the dazzled condition.\n\nSuccess The creature takes 2d6 bludgeoning damage and is blinded for 1 round. The creature can spend an Interact action wiping the salt water from its eyes to end the blinded condition.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"8lZhUreL1bRk1v4Z","book":"Pathfinder Adventure Path: Gatewalkers","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.buffeting-winds","name":"Buffeting Winds","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","concentrate","manipulate","nonlethal"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"5pokjjlq2v8f132j","formula":"2d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"5pokjjlq2v8f132j":"2d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You release a quick burst of wind that batters your living opponents without causing them lasting harm, while also blowing undead away. The wind deals 2d4 bludgeoning damage, which is nonlethal against living creatures. Against undead, the winds are more vicious, and the spell loses the nonlethal trait against such creatures. Each creature in the area must attempt a basic Reflex save. On a failure, undead creatures are also knocked back 5 feet (or 10 feet on a critical failure).\n\nHeightened (+1) The damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"xGFAGlonNySXrunq","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bullhorn","name":"Bullhorn","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","cantrip","concentrate","illusion","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You amplify your voice, loud enough for you to be heard easily at a great distance. For the duration, your voice can be heard loudly and clearly by all listeners within 500 feet, even if other ambient noise would otherwise block the sound. Despite the volume, this doesn't make your voice jarring or distracting. This doesn't increase the range or area of other auditory or linguistic effects, and physical barriers such as walls and doors still block or muffle your voice as normal.\n\nYour loud voice makes it easier to others, and the acoustics assist in Performing at a large venue. You gain a +1 status bonus to checks to Coerce and auditory Performance checks to at a large venue. You can Dismiss the spell.\n\nHeightened (5th) Your voice can be heard clearly up to 1,200 feet away.\n\nHeightened (7th) Your voice can be heard clearly up to 1 mile away.","source":{"provider":"PAIZO","sourceId":"W02bHXylIpoXbO4e","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.buoyant-bubbles","name":"Buoyant Bubbles","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a thin layer of foamy bubbles that adhere to the target, causing it to float in water and similar liquids. The target doesn't sink, even if it hasn't succeeded at a Swim check this round; an already-sinking target resurfaces with the bubbles' help over the course of 1 round. If on a plane where the water or liquid has a surface, the bubbles also prevent the target from diving beneath that surface unless it succeeds at a Fortitude save against your spell DC.\n\nHeightened (4th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"ILoXUDP84ru1hYLg","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.buzzing-bites","name":"Buzzing Bites","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cantrip","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"nq1rqbq4e9qh9tfk","formula":"1d4","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"nq1rqbq4e9qh9tfk":"1d4"}},"counteraction":false,"ritual":null,"description":"You evoke buzzing and crawling insects to climb onto a foe's body and bite, dealing 1d4 piercing damage and potentially sickening the foe, depending on its Fortitude save. Once this spell ends, the target becomes temporarily immune for 1 minute.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage.\n\nCritical Failure The target takes double damage and is Sickened 1 by the crawling insects. The sickened value can't be reduced below 1 while the spell is active.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"BItahht2hEHvR9Bt","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cackle","name":"Cackle","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","witch"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a quick burst of laughter, you prolong a magical effect you created. You Sustain a spell.","source":{"provider":"PAIZO","sourceId":"YVK3JUkPVzHIeGXQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.call-of-the-grave","name":"Call of the Grave","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fire a ray of sickening energy. Make a spell attack roll.\n\nCritical Success The target becomes Sickened 2 and Slowed 1 as long as it's Sickened.\n\nSuccess The target becomes Sickened 1.\n\nFailure The target is unaffected.","source":{"provider":"PAIZO","sourceId":"BH3sUerzMb2bWnv1","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.call-to-arms","name":"Call to Arms","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["auditory","concentrate","cursebound","emotion","focus","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are about to roll for initiative.\n\nYou cry out a call to arms, inspiring your allies to enter the fray. Each ally in the area gains a +2 status bonus to their initiative roll and gains temporary Hit Points equal to the spell's rank; these temporary Hit Points last for the spell's duration.\n\nHeightened (6th) The bonus increases to +3.\n\nHeightened (9th) The bonus increases to +4.","source":{"provider":"PAIZO","sourceId":"dqaCLzINHBiKjh4J","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.camel-spit","name":"Camel Spit","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["acid","attack","concentrate","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"ztsfuzsYaioKntEN","formula":"1d6","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"ztsfuzsYaioKntEN":"1d6"}},"counteraction":false,"ritual":null,"description":"You alter your stomach, esophagus, and tongue to be able to spit partially digested food with force. You can spit at a foe once you finish Casting the Spell and can repeat the attack once on each of your subsequent turns by taking a single action, which has the acid, attack, and concentrate traits. After your third spit attack, the spell ends. When you attack with camel spit, make a ranged spell attack roll against a creature within 15 feet, dealing 1d6 acid damage and causing the target to be for 1 round if you hit. On a critical hit, you deal double damage and the target takes @item.level[persistent,acid] damage.\n\nHeightened (+1) The damage increases by 1d6, and the persistent damage on a critical hit is increased by 1.","source":{"provider":"PAIZO","sourceId":"Hycyiw9xVzoIY4Dy","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.carryall","name":"Carryall","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A small platform of magical force materializes adjacent to you to carry cargo. It is or has a ghostly appearance, is 2 feet in diameter, and follows 5 feet behind you, floating just above the ground. It holds up to 5 Bulk of objects (if they can fit on it). Any objects atop the platform fall to the ground when the spell ends. You can Sustain the spell to move the platform up to 30 feet along the ground, to make it stay in place, or to have it return to you and resume following you. The spell ends if a creature tries to ride atop the platform, if the platform is overloaded, if anyone tries to lift or force the platform higher above the ground, or if you move more than 60 feet away from the platform.\nHeightened (4th) The platform can carry 10 Bulk, creatures can ride atop it, and it can hover in the air, not just on the ground","source":{"provider":"PAIZO","sourceId":"LvezN4a3kYf1OHMg","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.caustic-blast","name":"Caustic Blast","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["acid","cantrip","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"yI4fzrhnbFxup4Ep","formula":"1d8","damageType":"acid","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"yI4fzrhnbFxup4Ep":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You fling a large glob of acid that immediately detonates, spraying nearby creatures. Creatures in the area take 1d8 acid damage with a basic Reflex save; on a critical failure, the creature also takes (1+floor((@item.rank -1)/2))[persistent,acid] damage.\n\nHeightened (+2) The initial damage increases by 1d8, and the persistent damage on a critical failure increases by 1.","source":{"provider":"PAIZO","sourceId":"thAHF1zxNplLCJPO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.celestial-accord","name":"Celestial Accord","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","emotion","good","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"2 creatures that each have an unfriendly or worse attitude toward the other","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You intervene in a heated disagreement between two creatures, encouraging them to put aside their differences and find some common ground. The emotional heat of the prior moment becomes only a memory. Each target must make a Will save. A creature currently engaged in combat can't get a result worse than success, and a target that is subject to hostility from any other creature ceases to be affected by celestial accord.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is filled with doubt about its own intentions and feels an urge to cooperate with the other. It has a -2 status penalty to attack rolls against the other target for 1 round.\n\nFailure The creature can't make hostile actions against the other target and its attitude toward the other target improves to indifferent for the spell's duration.\n\nCritical Failure As failure, but the creature's attitude toward the other target improves to friendly for the duration and is indifferent thereafter (until something happens to change that attitude normally).","source":{"provider":"PAIZO","sourceId":"vZSWzkw0uF4iFWSM","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.charged-javelin","name":"Charged Javelin","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","concentrate","electricity","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"1","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d6","1":"1"}},"counteraction":false,"ritual":null,"description":"You fire a javelin of electricity that leaves a charged field around its target. Make a spell attack against the target's AC. The javelin deals 1d6 electricity damage and 1 persistent electricity damage.\n\nAs long as the target is taking persistent damage from this spell, creatures gain a +1 status bonus to attack rolls with metal weapons or electricity effects against the target, and the target takes a –1 status penalty to saves against electricity effects.\n\nCritical Success The javelin deals double damage, both initial and persistent.\n\nSuccess The javelin deals full damage.\nHeightened (+1) The initial damage increases by 1d6, and the persistent damage increases by 1.","source":{"provider":"PAIZO","sourceId":"g1eY1vN44mgluE33","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.charm","name":"Charm","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","emotion","incapacitation","manipulate","mental","subtle"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"To the target, your words are honey and your visage seems bathed in a dreamy haze. It must attempt a Will save, with a +4 circumstance bonus if you or your allies recently threatened it or used hostile actions against it.\n\nYou can Dismiss the spell. If you use hostile actions against the target, the spell ends. When the spell ends, the target doesn't necessarily realize it was charmed unless its friendship with you or the actions you convinced it to take clash with its expectations, meaning you could potentially convince the target to continue being your friend via mundane means.\n\nCritical Success The target is unaffected and aware you tried to charm it.\n\nSuccess The target is unaffected but thinks your spell was something harmless instead of charm, unless it identifies the spell.\n\nFailure The target's attitude becomes toward you. If it was Friendly, it becomes . It can't use hostile actions against you.\n\nCritical Failure The target's attitude becomes Helpful toward you, and it can't use hostile actions against you.\n\nHeightened (4th) The duration lasts until the next time you make your daily preparations.\n\nHeightened (8th) The duration lasts until the next time you make your daily preparations, and you can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"vLA0q0WOK2YPuJs6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.charming-push","name":"Charming Push","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","incapacitation","mental","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You push at the target's mind to deflect their ire. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target takes a –1 circumstance penalty to attack rolls and damage rolls against you.\n\nFailure The target can't use hostile actions against you.\n\nCritical Failure The target is Stunned 1 and can't use hostile actions against you.","source":{"provider":"PAIZO","sourceId":"KMFRKzNCq7hVNH7H","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.charming-touch","name":"Charming Touch","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","emotion","focus","incapacitation","manipulate","mental","subtle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature that could find you attractive","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You infuse your target with attraction, causing it to act friendlier toward you. The target attempts a Will save. It gains a +4 circumstance bonus to this save if you or your allies recently threatened or were hostile to it.\n\nCritical Success The target is unaffected and aware you tried to charm it.\n\nSuccess The target is unaffected but thinks your spell was something harmless instead of charming touch, unless it identifies the spell.\n\nFailure The target's attitude becomes toward you. If it was Friendly, it becomes . It can't use hostile actions against you. If you use a hostile action against the target, the spell ends. You can Dismiss the spell. After the spell ends, the target doesn't necessarily realize it was charmed unless its friendship with you or the actions you convinced it to take clash with its expectations. If it doesn't realize you charmed it, you could potentially convince it to continue being your friend via mundane means.\n\nCritical Failure As failure, but the target is helpful.","source":{"provider":"PAIZO","sourceId":"ut9IhJ9jSZSHDUop","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chastising-retort","name":"Chastising Retort","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","mental"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"HmxGQAIhO9ECJTuC","formula":"2d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"HmxGQAIhO9ECJTuC":"2d6"}},"counteraction":false,"ritual":null,"description":"Trigger A creature within range attempts a Deception check to or .\nYou unleash some choice words empowered with divine might. The creature takes 2d6 mental damage and must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is Stupefied 1 for [[/r 1d4 #rounds]]{1d4 rounds}.\n\nCritical Failure As failure, but the creature takes double damage and is Stupefied 2 for 1d4 rounds.\n\nThe creature can immediately choose to reveal the truth about its deception as a free action to immediately recover Hit Points equal to the mental damage it took and lose the stupefied condition from the spell. If it does, it quickly notes that its words and actions were lies, though it might need more time to explain the proper truth. If the creature used Deception to successfully Feint and it reveals the truth in this way, the target of the creature's Feint is no longer due to the successful Feint.\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"JkyUu62rLxcNT4K9","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.chilling-spray","name":"Chilling Spray","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"2d4","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A cone of icy shards bursts from your spread hands and coats the targets in a layer of frost. You deal 2d4 cold damage to creatures in the area; they must each attempt a Reflex save.\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and takes a –5-foot status penalty to its Speeds for 2 rounds.\n\nCritical Failure The creature takes double damage and takes a –10-foot status penalty to its Speeds for 2 rounds.\nHeightened (+1) The damage increases by 2d4.","source":{"provider":"PAIZO","sourceId":"8TQiFzGf4feoHeH0","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cinder-gaze","name":"Cinder Gaze","kind":"SPELL","rank":1,"rarity":"RARE","traits":["cleric","concentrate","focus","manipulate","prediction"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You've learned to read the future in the patterns of flames and smoke. Though inexact and often symbolic, these readings help prepare you for upcoming events. When Casting this Spell, you must be near a fire (of any size) for the duration. Upon completion, roll 1d4 for your prediction. The benefit lasts for 10 minutes or until expended, whichever comes first. After casting cinder gaze, you can't cast it again for 10 minutes.\n- Terrible Danger You gain a +2 status bonus to your next initiative roll.\n- New Life The next time you take damage, just before taking the damage, you gain 6 temporary Hit Points.\n- Vivid Insight (fortune) The next time you attempt a check to Recall Knowledge, roll twice and take the higher result.\n- Good Fortune (fortune) The next time you attempt a saving throw, roll twice and take the better result.\nHeightened (+1) The number of temporary Hit Points from new life increases by 2.","source":{"provider":"PAIZO","sourceId":"mOUwbIN1SUp8FyPR","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cleanse-cuisine","name":"Cleanse Cuisine","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 cubic foot","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform all food and beverages in the area into delicious fare, changing water into wine or another fine beverage, or enhancing the food's taste and ingredients to make it a gourmet treat. You can also choose to remove all toxins and contaminations from the food. This spell doesn't prevent future contamination, natural decay, or spoilage, nor does it make the food any more nutritious.\n\nHeightened (+2) Add another cubic foot to the area, which must be contiguous with the rest.","source":{"provider":"PAIZO","sourceId":"qXTB7Ec9yYh5JPPV","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clinging-ice","name":"Clinging Ice","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","cold","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"1d4","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"Freezing sleet and heavy snowfall collect on the target's feet and legs, dealing 1d4 cold damage and other effects depending on its Reflex save.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage, and takes a –5-foot circumstance penalty to its Speeds until the spell ends.\n\nCritical Failure The target takes double damage and a –10-foot circumstance penalty to its Speeds until the spell ends.\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"MraZBLJ4Be3ogmWL","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cloak-of-shadow","name":"Cloak of Shadow","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["aura","cleric","darkness","focus","manipulate","shadow"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You drape the target in a mantle of swirling shadows that make it harder to see. The cloak reduces bright light within a 20-foot emanation to dim light. This is a form of magical darkness and can therefore overcome non-magical light or attempt to counteract magical light.\n\nThe target can use condition gained from the shadows to , though observant creatures can still follow the moving aura of shadow, making it difficult for the target to become completely . The target can use an Interact action to remove the cloak and leave it behind as a decoy, where it remains, reducing light for the rest of the spell's duration. If anyone picks up the cloak after it's been removed by the original target, the cloak evaporates and the spell ends.","source":{"provider":"PAIZO","sourceId":"SE0fbgBj7atuukdv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clouded-focus","name":"Clouded Focus","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You sharpen a creature's senses, though more distant objects become hazy, indistinct, or muted to it. The target gains a +1 status bonus to Perception checks attempted with any of its precise senses. Furthermore, any imprecise senses the target has are sharpened to precise senses (though they don't receive the status bonus). However, the target can't perceive anything beyond a range of 20 feet with any of its senses.\n\nThe duration is determined by the target's Will save. You can allow allies to choose the outcome instead of attempting a saving throw.\nCritical Success The target is unaffected.\n\nSuccess The target is affected for 1 round.\n\nFailure The target is affected for 1 minute.\n\nCritical Failure As failure, but the target can't perceive anything beyond a range of 10 feet.\nHeightened (3rd) You can target up to 2 creatures.\n\nHeightened (6th) You can target up to 4 creatures.","source":{"provider":"PAIZO","sourceId":"XhgMx9WC6NfXd9RP","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.command","name":"Command","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["auditory","concentrate","linguistic","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the end of the target's next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You shout a command that's hard to ignore. You can command the target to approach you, run away (as if it had the condition), release what it's holding, drop , or stand in place. It can't or take any reactions until it has obeyed your command. The effects depend on the target's Will save.\n\nSuccess The creature is unaffected.\n\nFailure For the first action on its next turn, the creature must use a single action to do as you command.\n\nCritical Failure The target must use all its actions on its next turn to obey your command.\n\nHeightened (5th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"aIHY2DArKFweIrpf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.concordant-choir","name":"Concordant Choir","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","sonic"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"varies","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"}},"counteraction":false,"ritual":null,"description":"You unleash a dangerous consonance of reverberating sound, focusing on a single target or spreading out to damage many foes. The number of actions you spend Casting this Spell determines its targets, range, area, and other parameters.\n1 The spell deals 1d4 sonic damage to a single enemy, with a basic Fortitude save.\n\n2 (manipulate) The spell deals 2d4 sonic damage to all creatures in a , with a basic Fortitude save.\n\n3 (manipulate) The spell deals 2d4 sonic damage to all creatures in a , with a basic Fortitude save.\nHeightened (+1) The damage increases by 1d4 for the 1-action version, or 2d4 for the other versions.","source":{"provider":"PAIZO","sourceId":"TSyFZNAbqfkRrcq0","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.conductive-weapon","name":"Conductive Weapon","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","electricity","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 metal weapon that is unattended or is wielded by you or a willing ally","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel powerful electric current through the metal of a weapon, zapping anyone the item hits. The target becomes a +1 shock weapon. If any target of an attack with the weapon is wearing metal armor or is primarily made of metal, the electricity damage die from the shock rune is 1d12.","source":{"provider":"PAIZO","sourceId":"fkUCvynklBGb4LaI","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.connective-current","name":"Connective Current","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2},"cost":"occult"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 enemy","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a magical connection between you and an enemy, as if you were both caught in the same current. When the target takes a move action, you can Stride up to half your Speed in the same direction as the target as a reaction.\nHeightened (4th) You can Stride up to your Speed.\n\nHeightened (6th) As 4th, and you gain an additional reaction when you Cast this Spell and at the start of each of your turns that you can use only to make this movement.","source":{"provider":"PAIZO","sourceId":"t6vJnkyAYLXrOjQI","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cornucopia","name":"Cornucopia","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","druid","focus","healing","manipulate","plant","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d6+4","damageType":"vitality","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Vines twine into a wicker horn in your hands, and out spills a single fruit, nut, or similar small bit of produce. A creature who eats the produce with an Interact action regains 1d6+4 HP. The cornucopia, as well as any unconsumed pieces of fruit, wither away at the end of the duration.\nHeightened (+1) The cornucopia produces an additional piece of food. A creature can consume any amount of food from the same casting with a single Interact action. Eating six pieces of produce from the cornucopia gives as much nourishment as one square meal for a typical human.\n\n((@item.level)d6+(@item.level)*4)[vitality,healing]{Consume all produce}","source":{"provider":"PAIZO","sourceId":"vQuwLqtFFYt0K15N","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.counter-performance","name":"Counter Performance","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["bard","composition","concentrate","focus","fortune","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally within 60 feet rolls a saving throw against an auditory or visual effect.\n\nYour performance protects you and your allies. Roll a performance check for a type you know—it must be an auditory performance if the trigger was auditory or a visual one for a visual trigger, and this action gains the traits for the type of performance. You and allies in the area can use the better result between your Performance check and the saving throw.","source":{"provider":"PAIZO","sourceId":"WILXkjU5Yq3yw10r","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.courageous-anthem","name":"Courageous Anthem","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","concentrate","emotion","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You inspire yourself and your allies with words or tunes of encouragement. You and all allies in the area gain a +1 status bonus to attack rolls, damage rolls, and saves against fear effects.","source":{"provider":"PAIZO","sourceId":"IAjvwqgiDr3qGYxY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-mycoguardian","name":"Create Mycoguardian","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"parasitic fungal spores"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 dead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Fungus Lore (trained), Nature (expert)","secondaryChecks":"Fungus Lore (trained), Nature (expert)","secondaryCasters":1},"description":"You transform the target into an fungus creature with a level up to that allowed in the below table. There are many versions of this ritual, each specific to a particular type of mycoguardian, and the rituals that create rare mycroguardians are also rare.\n\nTable 7-1: Creatures Creation Rituals\n\nCreature Level\nSpell Rank Required\nCost\n\n-1 or 0\n2\n15 gp\n\n1\n2\n60 gp\n\n2\n3\n105 gp\n\n3\n3\n180 gp\n\n4\n4\n300 gp\n\n5\n4\n480 gp\n\n6\n5\n750 gp\n\n7\n5\n1,080 gp\n\n8\n6\n1,500 gp\n\n9\n6\n2,100 gp\n\n10\n7\n3,000 gp\n\n11\n7\n4,200 gp\n\n12\n8\n6,000 gp\n\n13\n8\n9,000 gp\n\n14\n9\n13,500 gp\n\n15\n9\n19,500 gp\n\n16\n10\n30,000 gp\n\n17\n10\n45,000 gp\n\nCritical Success The target becomes an fungal creature of the appropriate type. If it's at least 4 levels lower than you, you can make it a minion. This gives it the minion trait, meaning it can use 2 actions when you command it, and commanding it is a single action that has the auditory and concentrate traits. You can have a maximum of four minions under your control. If it's intelligent and doesn't become a minion, the mycoguardian is helpful to you. If it's unintelligent and doesn't become a minion, you can give it one simple command. It pursues that goal single-mindedly, ignoring any of your subsequent commands.\n\nSuccess As critical success, except an intelligent mycoguardian that doesn't become your minion is only friendly to you, and an unintelligent undead that doesn't become your minion leaves you alone unless you attack it. It marauds the local area rather than following your command.\n\nFailure You fail to create the mycoguardian.\n\nCritical Failure You create the mycoguardian, but its soul, tortured by your foul necromancy, is full of nothing but hatred for you. It attempts to destroy you.","source":{"provider":"PAIZO","sourceId":"6nPc5CPRUbSSRDP1","book":"Pathfinder #193: Mantle of Gold","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.create-water","name":"Create Water","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":0},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"As you cup your hands, water begins to flow forth from them. You create 2 gallons of water. If no one drinks it, it evaporates after 1 day.","source":{"provider":"PAIZO","sourceId":"WzLKjSw6hsBhuklC","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.creative-splash","name":"Creative Splash","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","illusion","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A deluge of paint or colorful illusions descend on the area, reflecting your personal creative specialty. Roll [[/r 1d4 #Creative Splash]] to determine the color of the illusion. Each creature in the area must succeed at a Will save or take the effect listed on the table for the color.\n1d4ColorFailureCritical Failure\n1White for 1 roundDazzled for 1 minute\n2RedEnfeebled 1 for 1 roundEnfeebled 2 for 1 round\n3YellowFrightened 1Frightened 2\n4BlueClumsy 1 for 1 roundClumsy 2 for 1 round","source":{"provider":"PAIZO","sourceId":"xTpp8dHZsNMDm75B","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.crescent-scepter","name":"Crescent Scepter","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["emotion","fear","focus","manipulate","mental","visual","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the beginning of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You hold up any object, which takes on the appearance of glowing regalia in the eyes of those who look on you, representing the political or religious institute most feared by each creature. If a creature attempts to attack you during the spell's duration, it must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature becomes Frightened 1, the penalty applying to its attack roll.\n\nFailure As success, but Frightened 2.","source":{"provider":"PAIZO","sourceId":"C8HWMMuB5tMhqJ5W","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.crown-of-prophets","name":"Crown of Prophets","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","focus","morph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"Nv7Qbk0in2t27lu9","formula":"2d4","damageType":"poison","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"Nv7Qbk0in2t27lu9":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Serpents sprout from your head, equally ready to bite your foes or offer you counsel. You gain a fangs unarmed attack that deals 1d6 piercing damage and has the agile, finesse, and versatile poison traits. The first time you Cast or Sustain this spell each round, you can perform one of the following as a free action.\n\nSerpentine Advice The snakes compete to offer you counsel. You gain the feat until the end of your turn, then you .\n\nToxic Prophecy (poison)\n\nRequirements A creature within 15 feet damaged you since the end of your last turn\n\nEffect The snakes spit toxic curses at the required creature, dealing 2d4 poison damage (basic Fortitude save).\n\nHeightened (+1) The poison damage dealt by Toxic Prophecy increases by 1d4.","source":{"provider":"PAIZO","sourceId":"h2DLv8TQV0Z83tQp","book":"Pathfinder #216: The Acropolis Pyre","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.crushing-ground","name":"Crushing Ground","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","earth","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[{"id":"0","formula":"2d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You tear open the ground then slam it shut. The target creature takes 2d6 bludgeoning damage with a Reflex save.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage, is , and takes a –10-foot circumstance penalty to Speed.\n\nCritical Failure The target takes double damage and is off-guard and . It can attempt to [[/act escape]] against your spell DC. If it doesn't Escape, the target takes an additional 2d6 bludgeoning damage when the spell ends.\n\nHeightened (+1) Increase the initial damage and additional damage by 2d6.","source":{"provider":"PAIZO","sourceId":"AiWtiVmyasyL42J8","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cry-of-destruction","name":"Cry of Destruction","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate","sonic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"1d8","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Your voice booms, smashing what's in front of you. Each creature and unattended object in the area takes 1d8 sonic damage. If you already dealt damage to an enemy this turn with a Strike or spell, increase the damage dice from this spell to d12s.\n\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"0H1ozccQGGFLUwFI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.curse-of-recoil","name":"Curse of Recoil","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","curse"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An enemy you can see is about to make a ranged attack.\nYou curse an enemy to suffer a kickback as they make a ranged attack, potentially causing them to miss. The triggering enemy attempts a Will save.\nCritical Success The target is unaffected.\n\nSuccess The recoil from their ranged attack causes the target to be until the beginning of their next turn.\n\nFailure The recoil imposes a –1 status penalty to the ranged attack and renders the target off-guard until the beginning of their next turn.\n\nCritical Failure The recoil imposes a –2 status penalty to the ranged attack and renders the target off-guard until the beginning of their next turn. Until the start of their next turn, any additional ranged attacks made with the same weapon, spell, or ability take the same penalty.","source":{"provider":"PAIZO","sourceId":"9uSBfK8EUVBrcNYx","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cutting-eye","name":"Cutting Eye","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","wizard"],"traditions":[],"casting":{"time":{"kind":"REACTION"},"requirements":"You're aware of the attack or spell."},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are the target of an attack or must attempt a saving throw against a spell.\nYour eyes open enviously, stealing the power of an opponent for yourself. You are not to the attacker or spellcaster until the beginning of your next turn. You gain a +2 circumstance bonus to your AC against the triggering attack or a +2 circumstance bonus to the triggering save.","source":{"provider":"PAIZO","sourceId":"mMyMOxYzMxADdO5M","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cycle-of-retribution","name":"Cycle of Retribution","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"KxmChmCzNHy5fbuW","formula":"1d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"KxmChmCzNHy5fbuW":"1d4"}},"counteraction":false,"ritual":null,"description":"An understanding of how violence begets more violence fills your target, causing it mental anguish in the form of splitting headaches when it attempts to take violent actions. The target must attempt a Will saving throw, with the following results.\nCritical Success The target is unaffected.\n\nSuccess The next time the target takes a hostile action, the target takes 1d4 mental damage; the spell's duration then ends.\n\nFailure The first time in a round when the target takes a hostile action, the target takes 1d4 mental damage.\n\nCritical Failure Each time the target takes a hostile action, the target takes 1d4 mental damage.\nHeightened (+1) The mental damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"m2i7N8tnqar3gZDZ","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.daemonic-pact","name":"Daemonic Pact","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert; you must be a daemon or an urdefhan)","secondaryCasters":0},"description":"You call upon the powers of Abaddon to grant you the assistance of a daemon. You call upon a daemon whose level can be no more than double daemonic pact's spell rank, two daemons whose levels are each at least 2 less than double the spell rank, or three daemons whose levels are each at least 3 less than double the spell rank.\n\nCritical Success You conjure the daemon or daemons, and they require nothing in return for their service.\n\nSuccess You conjure the daemon or daemons, who serve you willingly, but require a sacrifice in the form of spilled blood (either another creature's or your own).\n\nFailure You don't conjure any daemons.\n\nCritical Failure You don't conjure any daemons, and the self-sacrifice required to perform the ritual leaves you Drained 1 (or Drained 2 if the spell rank is 5 or higher).","source":{"provider":"PAIZO","sourceId":"Vpohy4XH1DaH95hT","book":"Pathfinder Bestiary 2","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.darkened-forest-form","name":"Darkened Forest Form","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","focus","polymorph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your apparition casts a feral shadow over your form. You can polymorph into any form listed in . When you transform into a form granted by a spell, you gain all the effects of the form you chose from a version of the spell heightened to darkened forest form's rank. Each time you Sustain this Spell, you can choose to change to a different shape from those available via any of the associated spells.\nHeightened (2nd) You can also transform into the forms listed in .\n\nHeightened (5th) You can also transform into the forms listed in .","source":{"provider":"PAIZO","sourceId":"BhJtCTLbngvZm8EA","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.daze","name":"Daze","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","manipulate","mental","nonlethal"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":true},"damage":[{"id":"0","formula":"1d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d6"}},"counteraction":false,"ritual":null,"description":"You push into the target's mind and daze it with a mental jolt. The jolt deals 1d6 mental damage, with a basic Will save. If the target critically fails the save, it is also Stunned 1.\n\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"4gBIw4IDrSfFHik4","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dazzling-flash","name":"Dazzling Flash","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","light","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You raise your religious symbol and create a blinding flash of light. Each creature in the area must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is for 1 round.\n\nFailure The creature is for 1 round and Dazzled for 1 minute. The creature can spend an Interact action rubbing its eyes to end the Blinded condition.\n\nCritical Failure The creature is Blinded for 1 round and Dazzled for 1 hour.\n\nHeightened (3rd) The area increases to a 30-foot cone.","source":{"provider":"PAIZO","sourceId":"zul5cBTfr7NXHBZf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deaths-call","name":"Death's Call","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A living creature within 20 feet of you dies, or an undead creature within 20 feet of you is destroyed.\n\nSeeing another pass from this world invigorates you. You gain temporary Hit Points equal to the triggering creature's level plus your spellcasting attribute modifier. If the triggering creature was undead, double the number of temporary Hit Points you gain. These last for the duration of the spell, and the spell ends if all the temporary Hit Points are depleted earlier.","source":{"provider":"PAIZO","sourceId":"HG4afO9EOGEU9bZN","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.debilitating-terror","name":"Debilitating Terror","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","fear","focus","incapacitation","mental","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You fill the target's mind with terrifying images to disrupt their combat focus. The target must attempt a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target takes a –1 circumstance penalty to attack and damage rolls against you.\n\nFailure The target can't use hostile actions against you.\n\nCritical Failure The target is Stunned 1 and can't use hostile actions against you.","source":{"provider":"PAIZO","sourceId":"AzTFMy9E9HQcLNRg","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.deep-breath","name":"Deep Breath","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["air","cantrip","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take an incredibly deep breath and can hold it for the spell's duration. You don't lose breath when hit, but you do lose all the air you inhaled if you speak (including to Cast a Spell). This spell doesn't create air; if you don't have air to breathe when you cast it, you get no benefit.\n\nHeightened (2nd) The duration increases to 1 hour, and you lose only 10 minutes of breath if you speak.\n\nHeightened (4th) The duration increases to 8 hours, and you lose only 10 minutes of breath if you speak.","source":{"provider":"PAIZO","sourceId":"C2DwamKrW6QHoDQg","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.defended-by-spirits","name":"Defended by Spirits","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","manipulate","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 ally and 1 enemy","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"81eNSgyiHHJo6CCk","formula":"1d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"81eNSgyiHHJo6CCk":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You entreat a spirit or the spiritual energies in your location to surround and protect an ally from an certain foe. Each time the enemy attacks and damages the ally, the enemy takes 1d6 spirit damage. The enemy is aware of these spirits and has a general sense that attacking the ally will draw the spirits' ire.\nHeightened (+2) The damage increases by 1d6.","source":{"provider":"PAIZO","sourceId":"oK8P3l5VvNKKDkZe","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.dehydrate","name":"Dehydrate","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"KCA7zyzlqSK9qPCG","formula":"1d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You stir the inner fire of all things within the area, driving out moisture. All creatures in the area take 1d6 persistent fire damage with a basic Fortitude save; creatures with the water or plant traits get a result one degree of success worse than they rolled. The spell ends for a creature when its persistent damage ends.\n\nA creature affected by dehydrate attempts an additional Fortitude save at the end of each of its turns, before rolling to recover from the persistent damage. It can forgo this additional save if it consumed water or a similar hydrating liquid within the last round (drinking typically requires a single action).\n\nSuccess The creature takes no additional effect.\n\nFailure The creature is Enfeebled 1 until the end of its next turn.\n\nCritical Failure The creature is Enfeebled 2 until the end of its next turn.\n\nHeightened (+2) The range increases by 10 feet, the burst increases by 5 feet, and the persistent fire damage increases by 3d6.","source":{"provider":"PAIZO","sourceId":"f9m9DayyGy3meqUX","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.déjà-vu","name":"Déjà Vu","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"1 creature","area":null},"duration":{"text":"2 rounds","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You loop a thought process in the target's mind, forcing it to repeat a moment's worth of actions. The target must attempt a Will save. If the target fails, whatever actions the target uses on its next turn, it must repeat on its following turn. The actions must be repeated in the same order and as close to the same specifics as possible. For example, if the target makes an attack, it must repeat the attack against the same creature, if possible, and if the target moves, it must move the same distance and direction, if possible, on its next turn.\n\nIf the target can't repeat an action, such as Casting a Spell that has been exhausted or needing to target a creature that has died, it can act as it chooses for that action but becomes Stupefied 1 until the end of its turn.","source":{"provider":"PAIZO","sourceId":"rerNA6YZsdxuJYt3","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.delay-consequence","name":"Delay Consequence","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"the triggering creature or object","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger A creature or object within range is hit by an attack.\nYou transpose the moment that the target would be injured to a point later in its timestream. Roll damage normally, but do not reduce Hit Points or apply any other effects of the attack until the spell's duration has elapsed. When the spell ends, the target is immediately affected by the attack, taking damage and being affected by any additional effects. You can Dismiss this spell.","source":{"provider":"PAIZO","sourceId":"3wmX7htzOXiHLdAn","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.demonic-pact","name":"Demonic Pact","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":["unholy"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert; you must be a demon)","secondaryCasters":0},"description":"You call in a favor from one demon of level 2 or lower, two demons of level 0 or lower, or three demons of level –1 or lower.\nCritical Success You conjure the demon or demons. They are eager to pursue the task, so they don't ask for a favor.\n\nSuccess You conjure the demon or demons. They are not eager to pursue the task, so they require a favor in return.\n\nFailure You don't conjure any demons.\n\nCritical Failure The demon or demons are angry that you disturbed them. They appear before you, but they immediately attack you.\nHeightened (+1) Increase the level of demon you call by 2 for each option.","source":{"provider":"PAIZO","sourceId":"tsKnoBuBbKMXkiz5","book":"Pathfinder Monster Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detect-magic","name":"Detect Magic","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","detection","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You send out a pulse that registers the presence of magic. You receive no information beyond the presence or absence of magic. You can choose to ignore magic you're fully aware of, such as the magic items and ongoing spells of you and your allies. You detect illusion magic only if that magic's effect has a lower rank than the rank of your detect magic spell. However, items that have an illusion aura but aren't deceptive in appearance (such as an invisibility potion) typically are detected normally.\nHeightened (3rd) You learn the rank or level of the most powerful magical effect the spell detects, as determined by the GM.\n\nHeightened (4th) As 3rd rank, but you also pinpoint the source of the highest-rank magic. Like for an imprecise sense, you don't learn the exact location, but can narrow down the source to within a 5-foot cube (or the nearest if larger than that).","source":{"provider":"PAIZO","sourceId":"gpzpAAAJ1Lza2JVl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detect-metal","name":"Detect Metal","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","detection","manipulate","metal"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You attune yourself to magnetic fields, becoming aware of the presence or absence of metallic objects, veins, and deposits within the area. You can choose to ignore metal you're fully aware of, such as the gear you and your allies wear and carry.\n\nYou detect metal hidden by illusions (such as ) only if the illusion has a lower rank than your detect metal spell. Against deceptive illusions, detect metal always notices an absence of metal when a non-metallic object is disguised as metallic. However, if the deception involves disguising one metallic object as another, such as pretending a copper coin is made of gold, detect metal registers only the presence of metal, not its type, even if the rank of your detect metal spell exceeds that of the illusion effect.\nHeightened (3rd) You can discern all types of metal you detected. Your spell can overcome deceptive illusory spells hiding one metal as another if the magic effect's rank is lower than that of your detect metal spell.","source":{"provider":"PAIZO","sourceId":"vJZ83ehQiM906lea","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.detect-poison","name":"Detect Poison","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","detection","manipulate"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 object or creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You detect whether a creature is venomous or poisonous, or if an object is poison or has been poisoned. You do not ascertain whether the target is poisonous in multiple ways, nor do you learn the type or types of poison. Certain substances, like lead and alcohol, are poisons and so mask other poisons.\n\nHeightened (2nd) You learn the number and types of poison.","source":{"provider":"PAIZO","sourceId":"QqxwHeYEVylkYjsO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.devouring-dark-form","name":"Devouring Dark Form","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","focus","morph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your apparition's dark power blends with your physical body, allowing you to take on terrifying characteristics of creatures that lurk in dark places. Your arms and legs transform into twisting tentacles. You gain a tentacle unarmed attack with 10-foot reach that deals 1d8 bludgeoning damage and has the grapple trait. The first time you Sustain this spell each round, you can attempt a single check with your tentacle against a creature within its reach.\n\nHeightened (2nd) You can choose to take on the shark battle form from instead of gaining a tentacle unarmed attack, heightened to the same level as this vessel spell. When you do, this spell loses the morph trait and gains the polymorph trait. You can attempt a jaws unarmed Strike against a creature within your reach each time you Sustain this spell.\n\nHeightened (5th) You can choose to take on the water elemental battle form from instead of gaining a tentacle unarmed attack, heightened to the same level as this vessel spell. When you do, this spell loses the morph trait and gains the polymorph trait. You can attempt an unarmed attack Strike against a creature within your reach each time you Sustain this spell.","source":{"provider":"PAIZO","sourceId":"wTldMJx0vyBAehrI","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.diabolic-edict","name":"Diabolic Edict","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing living creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You issue a diabolic edict, demanding the target perform a particular task and offering rewards for its fulfillment. It gains a +1 status bonus to attack rolls and skill checks related to performing the task. If it refuses to perform the task you proclaimed, it instead takes a -1 status penalty to all its attack rolls and skill checks.","source":{"provider":"PAIZO","sourceId":"Vctwx1ewa8HUOA94","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.diabolic-pact","name":"Diabolic Pact","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":["unholy"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert; you must be a devil)","secondaryCasters":0},"description":"You make an appeal to a powerful devil, asking them to bind some of their subordinates to your service. If you succeed, the devil sends you their choice of one devil of level 2 or lower, two devils of level 0 or lower, or three devils of level –1 or lower.\nCritical Success The devils are sent to you and serve you for [[/gmr 1d4 #Weeks]]{1d4 weeks}.\n\nSuccess The devils are sent to you and serve you for [[/gmr 1d4 #Days]]{1d4 days}.\n\nFailure Your request is denied.\n\nCritical Failure Not only is your request denied, but the powerful devil sends word of its displeasure to your master.\nHeightened (+1) Increase the level of devil sent to you by 2 for each option.","source":{"provider":"PAIZO","sourceId":"30BBep9U4BDV0EgQ","book":"Pathfinder Monster Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dim-the-light","name":"Dim the Light","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["darkness","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You cast a darkness or shadow spell.\n\nYou magnify the darkness from the triggering effect, causing the ambient light level to flicker briefly so you can slip from sight. You can immediately attempt a Stealth check to , and you can become to a creature even if you don't have cover and aren't otherwise concealed from that creature. You cease being hidden at the end of your turn unless you move into cover or become before then.","source":{"provider":"PAIZO","sourceId":"6UafOE1ZUbHamsZJ","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dimensional-assault","name":"Dimensional Assault","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","magus","teleportation"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TEXT","text":"half your Speed"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tumble through space, making a short dimensional hop to better position yourself for an attack. Teleport to any square in range that's within reach of a creature, and then make a melee Strike against one creature within your reach.","source":{"provider":"PAIZO","sourceId":"5p9Y4ACrtRM4gTpN","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.discern-secrets","name":"Discern Secrets","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"Your patron deigns to whisper a few secrets. The target can , , or as a free action. The target gains a +1 status bonus to the statistic used for the roll (a skill or Perception), as long as you Sustain the spell. The target is temporarily immune to discern secrets for 1 minute.\n\nHeightened (5th) You can target two creatures instead of one.","source":{"provider":"PAIZO","sourceId":"UmXhuKrYZR3W16mQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.discomfiting-whispers","name":"Discomfiting Whispers","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","aura","focus","misfortune","void"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"OxAN5ouL6iu9L10Y","formula":"1d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"OxAN5ouL6iu9L10Y":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You are surrounded by an aura of spiteful murmurings that incite bad luck and punish failure. Each creature that starts their turn within the area of this spell must succeed at a Will save or roll twice on their first attack roll that round and take the lower result. If an attack roll modified in this way results in a failure, the creature that rolled the failed attack takes 1d6 void damage.\n\nHeightened (+2) The void damage dealt on a failure increases by 1d6.","source":{"provider":"PAIZO","sourceId":"t1e3U2eluRsp2izf","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.disguise-magic","name":"Disguise Magic","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 item or spell effect","area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You alter how an item's or spell's magical aura appears to effects like detect magic. You can hide the auras entirely, have an item register as a common item of lower level, or make a spell register as a common spell of the same or lower rank. You can Dismiss the spell. A caster using or of a higher rank than disguise magic can attempt to disbelieve the illusion using the skill matching the tradition of the spell (Arcana for arcane, Religion for divine, Occultism for occult, or Nature for primal). Further attempts by the same caster get the same result as the initial check to disbelieve.\n\nHeightened (2nd) You can Cast this Spell on a creature, disguising all items and spell effects on it.","source":{"provider":"PAIZO","sourceId":"PRrZ7anETWPm90YY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.distortion-lens","name":"Distortion Lens","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"SQUARE","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":3,"damage":{},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You create a magical lens that distorts space as best suits you. You create the lens in an area in range, even suspended in midair. If your or an ally's ranged attack passes through the lens, the attack gains an additional 10 feet of range; if an enemy's ranged attack would pass through the lens, it requires an additional 10 feet of range to move through, though the enemy knows before using its ability whether the interference puts the target out of range. An ally whose space overlaps the lens can increase the range of its ranged attacks, but an enemy whose space overlaps the lens doesn't reduce the range of its ranged attacks.\n\nThe first time each round you Sustain the Spell, you can choose to relocate it to another area within range. The lens disappears if you cast distortion lens again.\nHeightened (+3) The lens increases or decreases the range of abilities by an additional 5 feet.","source":{"provider":"PAIZO","sourceId":"WOM9alxiTdp0HEVD","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.distracting-decoy","name":"Distracting Decoy","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","ranger","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a colorful, fast-moving shape, such as a small bird or other animal that draws your target's eye. They must attempt a Will save.\nSuccess The creature is unaffected.\n\nFailure The creature is until the start of your next turn.\n\nCritical Failure As failure, but the creature also takes a –2 circumstance penalty to attacks while it's off-guard.","source":{"provider":"PAIZO","sourceId":"z8bHh8KVttslQIU9","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.div-pact","name":"Div Pact","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (expert; you must be a div)","secondaryCasters":0},"description":"You call upon the powers of Abaddon to grant you the assistance of a div. You call upon a div whose level can be no more than double div pact's spell rank, two divs whose levels are each at least 2 less than double the spell rank, or three divs whose levels are each at least 3 less than double the spell rank.\n\nCritical Success You conjure the div or divs, and they require nothing in return for their service.\n\nSuccess You conjure the div or divs. They are not eager to pursue the task, so they require a favor in return.\n\nFailure you don't conjure any divs.\n\nCritical Failure You don't conjure any divs, and they send a spiritual backlash that denies your use of any of your innate divine spells for 24 hours. If you are under the effect of any of your innate divine spells, the durations end.","source":{"provider":"PAIZO","sourceId":"D8cWhrzcsd43OlIX","book":"Pathfinder Monster Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.divine-lance","name":"Divine Lance","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["attack","cantrip","concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d4","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You unleash a beam of divine energy. Make a ranged spell attack against the target's AC. On a hit, the target takes 2d4 spirit damage (double damage on a critical hit).\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"qwZBXN6zBoB9BHXE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.divine-plagues","name":"Divine Plagues","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","disease","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your deity sends wracking plagues. The target must attempt a Fortitude save. When you Cast the Spell, decide whether the disease inflicts the clumsy, enfeebled, or stupefied condition.\n\nSuccess The target is unaffected.\n\nFailure The target is afflicted with stage 1 divine plague.\n\nCritical Failure The target is afflicted with stage 2 divine plague.\nDivine Plague (disease) Level 1\n\nStage 1 Clumsy 1, Enfeebled 1, or Stupefied 1 (1 round)\n\nStage 2 Slowed 1 and clumsy 1, enfeebled 1, or stupefied 1 (1 round)\n\nStage 3 clumsy 1, enfeebled 1, or stupefied 1 and the target can't recover from the condition until they are cured (1 day)\nHeightened (5th) The divine plague disease gains the virulent trait. The condition value for the clumsy, enfeebled, or stupefied condition is 2 instead of 1","source":{"provider":"PAIZO","sourceId":"NkeLctXo9FLGnDhi","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.diviners-sight","name":"Diviner's Sight","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","fortune","wizard"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing living creature","area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You glimpse into the target's future. Roll a d20; when the target attempts a non-secret saving throw or skill check, it can use the number you rolled instead of rolling, and the spell ends. Alternatively, you can instead reveal the result of the die roll for one of the target's secret checks during the duration, and the spell ends. Casting it again ends any active diviner's sight you have cast, as well as any active diviner's sight on the target.","source":{"provider":"PAIZO","sourceId":"oFwmdb6LlRrh9AUT","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.dizzying-colors","name":"Dizzying Colors","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","illusion","incapacitation","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":15}},"duration":{"text":"1 or more rounds (see below)","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You unleash a swirling multitude of colors that overwhelms creatures based on their Will saves.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is for 1 round.\n\nFailure The creature is Stunned 1, for 1 round, and dazzled for 1 minute.\n\nCritical Failure The creature is stunned for 1 round and blinded for 1 minute.","source":{"provider":"PAIZO","sourceId":"UKsIOWmMx4hSpafl","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.draconic-barrage","name":"Draconic Barrage","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d4"}},"counteraction":false,"ritual":null,"description":"You shape energy into a small group of tiny dragons (or other serpentine creatures) that flit around you. Choose fire, force, mental, or spirit damage when you Cast the Spell. For the duration of the spell, your Strikes with weapons or unarmed attacks deal 1 additional damage of the chosen type, as the dragons add their energy to your attacks. You can Sustain the spell to change the damage type.\n\nIn addition, you can Sustain the spell to have the dragons fly off to bombard a creature within 60 feet. That creature takes 2d4 damage of the chosen type (basic Reflex save). Once the dragons have been used in this way, they wink out of existence and the spell ends.\nHeightened (+1) The additional amount of damage from the dragons increases by 1 and the damage dealt by the dragons' bombardment increases by 2d4.","source":{"provider":"PAIZO","sourceId":"S6Kkk15MWGqzC00a","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.draw-ire","name":"Draw Ire","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"1d10","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"You cause mental distress to a creature, goading it to strike back at you. You deal 1d10 mental damage to the creature and cause it to take a -1 status penalty to attack rolls against creatures other than you. The creature must attempt a Will saving throw.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and the penalty. The spell ends at the end of the target's next turn.\n\nFailure The target takes full damage and the penalty.\n\nCritical Failure The target takes double damage, and the status penalty is -2.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"jsWthW1Qy6tg3SwD","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.draw-moisture","name":"Draw Moisture","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw water out of an object, possibly to clean up spills or quickly dry a soaked book or shirt. You draw up to a pint of water from the object; this dries objects of less than 1 Bulk. The water collects in a globule floating in your hand, which you can direct into a nearby container as part of Casting the Spell; otherwise, it splashes to the ground. Repeated applications of draw moisture can be used to dry larger objects, although doing so might take significant time. You can use this spell in especially humid environments to condense drinkable water from the air, though typically, you can't draw more than a few cups before depleting the ambient moisture.","source":{"provider":"PAIZO","sourceId":"lXsFKdaOz9t9w11U","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.earths-bile","name":"Earth's Bile","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","earth","fire","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"INFFw4nT75jXjS4B","formula":"1d4","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"Ri9pmfc1Jkvm7j0x","formula":"1d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"INFFw4nT75jXjS4B":"1d4","Ri9pmfc1Jkvm7j0x":"1d4"}},"counteraction":false,"ritual":null,"description":"Your apparition is the will of lava and magma made manifest, the earth's molten blood unleashing devastating bursts of liquid stone and unquenchable fire at your command. When you Cast this Spell and the first time you Sustain it each round thereafter, choose an area within range. Each creature in the area takes 1d4 fire damage, 1d4 bludgeoning damage, and (ceil(@item.rank/2))[persistent,fire] damage (the persistent fire damage is negated on a successful save).\nHeightened (+2) The fire and bludgeoning damage each increase by 1d4, and the persistent fire damage increases by 1.","source":{"provider":"PAIZO","sourceId":"PrlR2sLWeiuTcPF2","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.earthworks","name":"Earthworks","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","earth","focus","manipulate","wizard"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a ripple of earth, you raise small barriers from the ground. The ground in the area becomes difficult terrain. The spell's area is a if you spent 1 action to cast it, a if you spent 2 actions, or a if you spent 3 actions. A creature can Interact to clear the barriers from one 5-foot square adjacent to it.\n\nHeightened (4th) You pull the barriers to float in the air, causing the spell to function as difficult terrain for flying creatures","source":{"provider":"PAIZO","sourceId":"ffz6wlSMzhaDpjg6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.eat-fire","name":"Eat Fire","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","fire","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the end of your next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You would take fire damage.\n\nYou consume and ingest fire, making it less harmful to you. You gain resistance 5 to fire damage until the end of the current turn. During the remaining duration of the spell, you can use the Belch Smoke action. The spell ends if you fall , inhale, or exhale (this includes speaking).\n\nBelch Smoke 1 You exhale what remains of the smoke, ending the spell and creating a smoke cloud in a within 20 feet. All creatures within the smoke cloud are , and all other creatures are concealed to them. The smoke lasts for 1 minute or until dispersed by a strong wind.\n\nHeightened (+3) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"FWuLUKIbkJZjBiuA","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.echoing-weapon","name":"Echoing Weapon","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","sonic"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 weapon","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel magical energy into the target weapon, and the air around it faintly hums each time you strike a blow, as the impact is absorbed into the weapon. If a creature is wielding the weapon at the end of its turn, the weapon discharges a burst of sound targeting one creature adjacent to the wielder (if any). The sonic damage this deals is equal to the number of successful Strikes with the target weapon that the wielder made that turn (to a maximum of 4 sonic damage if the wielder hits with four Strikes).\n\nHeightened (+2) The sonic damage increases by 1 per Strike (and the maximum damage increases by 4).","source":{"provider":"PAIZO","sourceId":"vtCCVe869shMCJMj","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.eject-soul","name":"Eject Soul","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","incapacitation","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 living creature that has a soul","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your touch disrupts the connection between body and soul, possibly forcing the soul out of the body altogether. The target must attempt a Fortitude save. You can allow allies to choose the degree of success instead of rolling a saving throw.\nSuccess The target is unaffected.\n\nFailure The target is Stunned 1 as its soul briefly loses its connection to their body.\n\nCritical Failure The target's soul exits its body and the target's body becomes stunned for 1 round. While their body is stunned in this way, the target remains fully aware in soul form; they simply can't consciously move their body (though the body makes basic instinctual defensive movements). The target's soul has the incorporeal trait, is , and has a fly Speed of 60 feet. It can't attack, cast spells, or attempt any skill checks that require a physical body, and it must always maintain line of effect to the target's body. When the target's body ceases being stunned, the target's soul instantly returns to their body as the target wakes.\nHeightened (+3) If a willing ally chooses to critically fail, they can stay in soul form for 1 additional round.","source":{"provider":"PAIZO","sourceId":"rVhHaWqUsVUO4GuY","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.electric-arc","name":"Electric Arc","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","electricity","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 or 2 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"An arc of lightning leaps from one target to another. Each target takes 2d4 electricity damage with a basic Reflex save.\n\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"kBhaPuzLUSwS6vVf","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.elemental-betrayal","name":"Elemental Betrayal","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron uses its superior command of the elements, empowering them to undermine your foe. When you Cast this Spell, choose air, earth, metal, fire, water, or wood. The target gains weakness 2 to that trait.\n\nHeightened (+2) Increase the weakness by 1.","source":{"provider":"PAIZO","sourceId":"f9uqHnNBMU0774SF","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-counter","name":"Elemental Counter","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","concentrate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or a creature within 60 feet rolls a saving throw against a spell with the earth, fire, metal, plant, water, or wood trait, or are targeted by a spell attack with such a trait.\n\nRequirements You have a spell slot from which you could Cast a Spell of the triggering spell's countering element; see text.\n\nEach element in the elemental cycle counters another, and you can use your elemental spells to protect against elements they counter. You lose your spell slot as if you had cast the triggering spell. You then attempt to counteract the triggering spell, using the rank of the spell you lost for the counteract rank. You can lose a plant or wood spell to counter earth, an earth spell to counter water, a water spell to counter fire, a fire spell to counter metal, or a metal spell to counter plant or wood.","source":{"provider":"PAIZO","sourceId":"fHawnhOHwzr4Mwr7","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-sentinel","name":"Elemental Sentinel","kind":"RITUAL","rank":1,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"precious metals, rare incense, and herbs worth a total value of 15 gp per spell rank"},"targeting":{"range":{"kind":"NONE"},"target":"1 object","area":null},"duration":{"text":"unlimited","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana (expert) or Occultism (expert)","secondaryCasters":0},"description":"You place a tiny elemental wisp within a single object, usually a mirror, statue, or other mundane-looking item, to serve as an alarm. Shattering or otherwise destroying the object frees the wisp and ends the ritual's effect even if the object is magically restored.\n\nCritical Success The elemental wisps inhabits the object and willingly serves you to the best of its ability. The wisp becomes aware of the target object's surroundings and can telepathically contact you with a range of 500 feet. It reports to you about intruders or other changes to the room in which it's located. You must tell the wisp what the criteria for the reports will be-for instance, when anyone not openly wearing a certain symbol enters the room or when an item is removed. The wisp has a +5 Perception modifier and observes the room using normal vision, normal hearing, and touch.\n\nSuccess As critical success, but the range of the telepathy is 100 feet and the wisp's Perception modifier is +3.\n\nFailure You're unable to harness the spirit. The ritual fails.\n\nCritical Failure The elemental wisp is trapped in the object as with a success, but it refuses or is somehow unable to help you. The elemental might have extremely low Intelligence or simply be spiteful. Regardless, the object's reports are always misleading.\n\nHeightened (4th) The range of the telepathic link increases, allowing the wisp to contact you anywhere on the same planet. Its Perception modifier increases to +10, or +12 on a critical success.\n\nHeightened (6th) As 4th level, except the wisp can see invisibility, and its Perception modifier increases to +15, or +17 on a critical success.","source":{"provider":"PAIZO","sourceId":"rOwOLlfVgLMg1FND","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.elemental-toss","name":"Elemental Toss","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"With a flick of your wrist, you fling a chunk of your elemental matter at your foe. Make a ranged spell attack roll, dealing 1d8 damage on a success and double damage on a critical success. This spell deals damage according to your elemental influence (for instance, slashing for air or fire for fire) and has your element's trait.\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"0JUOgbbFCapp3HlW","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.elysian-whimsy","name":"Elysian Whimsy","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","incapacitation","manipulate","mental"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You overwhelm the target with an unexpected and unpredictable desire if it fails a Will save. Roll [[/r 1d4]] to determine the spell's effect.\n\n1d4\nEffect\n\n1\nThe target feels a powerful urge to dance. For 1 round, it takes a –5-foot status penalty to its Speeds (-10-foot status penalty on a critical failure), capering and prancing as it moves.\n\n2\nThe target is compelled to loudly sing a song. Its first action on its next turn must be to a song it knows, or to babble pleasingly if it knows no songs. On a critical failure, the target must use all its actions on its next turn to Perform a song.\n\n3\nThe target is filled with an irresistible urge to support a nearby creature's entertainment career. Its first action on its next turn must be to prepare to Aid a Perform check for the nearest creature it can see and the target can use the next reaction it gains only to Aid the creature it helped. On a critical failure, it must spend all its actions on its next turn preparing to Aid a Perform check.\n\n4\nThe target is overcome with a desire to give away its wealth. Its first action on its next turn must be to Interact to pull out a non-magical item of value it is carrying (such as a coin, piece of jewelry, or an item made of precious metal), if it doesn't already have one in hand. It then Releases the valuable item. If the target neither holds nor carries an appropriate item, it instead spends its first action loudly apologizing for having nothing to give. On a critical failure, the target must spend any actions remaining on its turn apologizing for not giving more.","source":{"provider":"PAIZO","sourceId":"oPVyu2a0K3aTVIR8","book":"Pathfinder #183: Field of Maidens","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.embodiment-of-battle","name":"Embodiment of Battle","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["animist","focus"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your apparition guides your attacks and imparts its skill to your movements. For the duration, your proficiency with martial weapons is equal to your proficiency with simple weapons, you gain a +1 status bonus to attack and damage rolls made with weapons or unarmed attacks, and you gain the reaction; this reaction gains the apparition trait. The instincts of an apparition of battle run contrary to the use of magic; for the duration of this spell, you take a –2 status penalty to your spell attack modifiers and your spell DCs.\n\nHeightened (4th) The status bonus to attack and damage rolls granted by this spell is increased to +2.\n\nHeightened (7th) The status bonus to attack and damage rolls granted by this spell is increased to +3.","source":{"provider":"PAIZO","sourceId":"X4On99Nti8gjWywG","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.empty-inside","name":"Empty Inside","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","concentrate","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You inject a sliver of the void into your mind, momentarily remaking it into a bleak and empty place. Attempt a counteract check against one emotion effect affecting you.\n\nHeightened (5th) You can attempt counteract checks against any number of emotion effects affecting you.","source":{"provider":"PAIZO","sourceId":"0cF9HvHzzWSbCFBP","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.endure","name":"Endure","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":null,"description":"You invigorate the touched creature's mind and urge it to press on. You grant the touched creature 5 temporary Hit Points that last for 1 minute.\nHeightened (+1) The temporary Hit Points increase by 5.","source":{"provider":"PAIZO","sourceId":"4c1c6eNzU1PFGkAy","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.enfeeble","name":"Enfeeble","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sap the target's strength, depending on its Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Enfeebled 1 until the start of your next turn.\n\nFailure The target is Enfeebled 2 for 1 minute.\n\nCritical Failure The target is Enfeebled 3 for 1 minute.","source":{"provider":"PAIZO","sourceId":"J7Y7tl0bbdz7TcCc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.entreat-spirit","name":"Entreat Spirit","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"You must be Bonded with a Spirit"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You invite a spirit you've bonded with to bolster your mind. You gain a +1 status bonus to an Intelligence-, Wisdom-, or Charisma-based skill of your choice. Additionally, you gain a +1 status bonus to saving throws against curse, death, emotion, and fear effects.\nHeightened (4th) The status bonus to the skill and your saving throws increases to +2.\n\nHeightened (8th) The status bonus to the skill and your saving throws increases to +3.","source":{"provider":"PAIZO","sourceId":"Yph1UqZU8vMc9bJG","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.equal-footing","name":"Equal Footing","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature with a land Speed greater than yours","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You level the field between yourself and another creature, hampering its movements if it's quicker than you. The target attempts a Will save.\nCritical Success The target is unaffected.\n\nSuccess The target is Clumsy 1 and takes a –10-foot status penalty to all its Speeds until the end of your next turn.\n\nFailure The target is clumsy 1 and takes a –15-foot status penalty to all its Speeds for 1 minute. During this time, it can't benefit from bonuses to its Speeds or take other penalties to its Speeds.\n\nCritical Failure The target is Clumsy 2 and takes a –15-foot status penalty to all its Speeds for 1 minute. During this time, it can't benefit from bonuses to its Speeds or take other penalties to its Speeds.","source":{"provider":"PAIZO","sourceId":"Z2oSFY2fT8zLkK4P","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.evil-eye","name":"Evil Eye","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cantrip","curse","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your patron's resentment manifests in a baleful, envious gaze. The target becomes Sickened 1 if it fails a Will save (or sickened 2 on a critical failure). This condition value can't be reduced below 1 while the spell is active and you can see the target.","source":{"provider":"PAIZO","sourceId":"f45JpY7Ph2cAJGW2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.evolution-surge","name":"Evolution Surge","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","morph","summoner"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"target":"your eidolon","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You flood your eidolon with power, creating a temporary evolution in your eidolon's capabilities. Choose one of the following effects:\n\n- Your eidolon gains low-light vision and darkvision.\n\n- Your eidolon gains as an imprecise sense up to 30 feet.\n\n- Your eidolon can breathe underwater and gains a swim Speed equal to its land Speed or 30 feet, whichever is less. Alternatively, if your eidolon is normally aquatic, it can breathe air and gains a land Speed equal to its swim Speed or 30 feet, whichever is less. Either way, it gains the amphibious trait.\n\n- Your eidolon gains a +20-foot status bonus to its Speed.\n\nHeightened (3rd) Add the following options to the list of effects you can choose:\n\n- Your eidolon becomes Large, instead of its previous size. This increases your eidolon's reach to 10 feet but doesn't change any other statistics for your eidolon. Because of the special link you share, you can ride your eidolon without getting in each other's way. If another creature tries to ride your eidolon, both you and the riding creature each regain only 2 actions at the start of your turns each round, as normal.\n\n- Your eidolon gains a climb Speed equal to its land Speed.\n\nHeightened (5th) Add the options from the 3rd-rank version and the following options to the list of effects you can choose:\n\n- Your eidolon becomes Huge, instead of its previous size. This has the same effects as the 3rd-rank option to become Large, except your eidolon's reach increases to 15 feet.\n\n- Your eidolon gains a fly Speed equal to its Speed.","source":{"provider":"PAIZO","sourceId":"lV8FkHZtzZu7Cy6j","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.exchange-image","name":"Exchange Image","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You have the humanoid trait"},"targeting":{"range":{"kind":"TOUCH"},"target":"you and 1 other humanoid","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"To mislead pursuers, the Lacunafex developed the means to swap visages. You trade appearances with the target, with the effects depending on the result of the target's Will saving throw. Willing and targets automatically critically fail this saving throw.\n\nCritical Success No effect.\n\nSuccess You take on the target's appearance, and they take yours. This has the same effects as a 1st-rank spell, except that the target can't Dismiss the disguise. The duration is 1 minute or until Dismissed.\n\nFailure As success, but the duration is 1 hour or until Dismissed.\n\nCritical Failure As success, but the duration is 24 hours.","source":{"provider":"PAIZO","sourceId":"znMvKqcRDilIVMwA","book":"Pathfinder #147: Tomorrow Must Burn","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.extend-boost","name":"Extend Boost","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","spellshape","summoner"],"traditions":[],"casting":{"time":{"kind":"FREE_ACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus on the intricacies of the magic binding you to your eidolon to extend the duration of your boost eidolon or reinforce eidolon spell. If your next action is to cast or , attempt a skill check with the skill associated with the tradition of magic you gain from your eidolon (such as Nature for a primal eidolon). The DC is usually a standard-difficulty DC of your level, but the GM can assign a different DC based on the circumstances. The effect depends on the result of your check.\n\nCritical Success The spell lasts 4 rounds.\n\nSuccess The spell lasts 3 rounds.\n\nFailure The spell lasts 1 round, but you don't spend the Focus Point for casting this spell.","source":{"provider":"PAIZO","sourceId":"CR8OKDbeFJoZbOCu","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.face-in-the-crowd","name":"Face in the Crowd","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["cleric","focus","manipulate","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"While in a crowd of roughly similar creatures, your appearance becomes bland and nondescript. You gain a +2 status bonus to Deception and Stealth checks to go incognito among the crowd, and you ignore difficult terrain caused by the crowd. This counts as setting up a disguise for the use of Deception and you add your level even if you're untrained.\n\nHeightened (3rd) The spell gains a range of 10 feet and can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"yH13KXUK2x093NUv","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.faerie-dust","name":"Faerie Dust","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental","sorcerer"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5,"text":"5-foot burst or more"}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":3,"damage":{}},"counteraction":false,"ritual":null,"description":"You sprinkle magical dust in the spell's area, making those within easier to trick. Each creature in the area must attempt a Will save. For each additional action you use when Casting the Spell, increase the burst's radius by 5 feet.\nSuccess The creature is unaffected.\n\nFailure The creature can't use reactions and takes a -2 status penalty to Perception checks and Will saves.\n\nCritical Failure As failure, and the creature also takes a -1 status penalty to Perception checks and Will saves for 1 minute.\n\nHeightened (+3) The initial radius increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"IkS3lDGUpIOMug7v","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fashionista","name":"Fashionista","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's clothes are transformed into ostentatious attire that epitomizes high-end local fashion. No details of the target's appearance transform other than their clothes, so their weapons or armor remain unchanged in appearance. The target gains a +1 status bonus on Deception checks to . You can Dismiss this spell. At the end of the spell's duration, the target's clothes revert to their original appearance.\n\nHeightened (+2) The status bonus increases by 1, to a maximum of +4 at 7th rank.","source":{"provider":"PAIZO","sourceId":"W0YqtSVwfFImGgdK","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fated-healing","name":"Fated Healing","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","linguistic","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"2 creatures who are hostile toward each other","area":null},"duration":{"text":"5 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"WhDZWzgmADIIVxKO","formula":"1d4","damageType":"untyped","kind":"HEALING","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"WhDZWzgmADIIVxKO":"1d4"}},"counteraction":false,"ritual":null,"description":"You speak about the consequences of actions people take against each other and how it's possible to break cycles of violence simply by making a different choice. The targets regain 1d4 Hit Points at the end of each of their own turns while the spell is in effect. If a target uses a hostile action against the other target, the spell ends for the target that used the hostile action.\nHeightened (+1) The targets regain an additional 1d4 Hit Points at the end of their own turns.","source":{"provider":"PAIZO","sourceId":"X3RUan7TVqo6UpUG","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fear","name":"Fear","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","emotion","fear","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You plant fear in the target; it must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Frightened 1.\n\nFailure The target is Frightened 2.\n\nCritical Failure The target is Frightened 3 and for 1 round.\n\nHeightened (3rd) You can target up to five creatures.","source":{"provider":"PAIZO","sourceId":"4koZzrnMXhhosn0D","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fey-abeyance","name":"Fey Abeyance","kind":"RITUAL","rank":1,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"rare oils, cold iron bells worth at least 5 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Nature (trained)","secondaryChecks":"Crafting, Intimidation, Occultism, Performance","secondaryCasters":1},"description":"Area An enclosed area up to 60 feet × 60 feet, up to 20 feet high\n\nYou ward an area with cold iron bells, protecting it from the influence of the first world. Fey creatures feel uncomfortable within the area and all physical attacks against them are considered cold iron for the purposes of their Weaknesses and Resistances. Furthermore, you set up bells within 3 squares within the area (usually at entrances). When a fey creature begins its turn in a square containing bells, it takes mental damage equal to its Weakness to cold iron, if any. This damage is nonlethal.\n\nCritical Success You may designate up to 6 squares to contain bells.\n\nSuccess The ritual succeeds.\n\nFailure The ritual has no effect.\n\nCritical Failure The ritual has no effect and attracts the attention of a troublesome fey creature. At the GM's discretion, it might be hostile or merely mischievous.","source":{"provider":"PAIZO","sourceId":"GzlVI3qYdCtUigLz","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.figment","name":"Figment","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["cantrip","concentrate","illusion","manipulate","subtle"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a simple illusory sound or vision. A sound adds the auditory trait to the spell and the sound can't include intelligible words or elaborate music. A vision adds the visual trait, can be no larger than a 5-foot cube, and is clearly crude and undetailed if viewed from within 15 feet. When you Cast or Sustain the Spell, you can attempt to with the illusion, gaining a +2 circumstance bonus to your Deception check. If the attempt fails against a creature, that creature disbelieves the figment.","source":{"provider":"PAIZO","sourceId":"0zU8CPejjQFnhZFI","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fire-ray","name":"Fire Ray","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","cleric","concentrate","fire","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"until the end of the target's next turn","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"A blazing band of fire arcs through the air, lighting your opponent and the ground they stand upon on fire. Make a spell attack roll against the target's AC. The ray deals 2d6 fire damage on a hit (or double damage on a critical hit). On any result other than a critical failure, the ground in the target's space catches fire, dealing (@item.rank)d6[fire] damage to each creature that ends its turn in one of the squares.\n\nHeightened (+1) The ray's initial damage increases by 2d6, and the fire damage dealt by the burning space increases by 1d6.","source":{"provider":"PAIZO","sourceId":"oJKZi8OQgmVXHOc0","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.flashy-disappearance","name":"Flashy Disappearance","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a puff of colorful smoke that quickly disperses while you become temporarily . You become to all creatures unless they can see invisible creatures. You Stride. At the end of your movement, if you have cover, greater cover, or concealment, attempt a stealth check to Hide. You gain a +2 status bonus to this Stealth check. The invisibility then ends, and you either become or to creatures as determined by your check to Hide, if you made one.","source":{"provider":"PAIZO","sourceId":"YgbYvkLvnWJ4WfEA","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.fleet-step","name":"Fleet Step","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You gain a +30-foot status bonus to your Speed.","source":{"provider":"PAIZO","sourceId":"aEM2cttJ2eYcLssW","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flense","name":"Flense","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","concentrate","manipulate"],"traditions":["ARCANE","DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature or corpse","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"F7dmCJUYa7dzGz9n","formula":"2d6","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"F7dmCJUYa7dzGz9n":"2d6"}},"counteraction":false,"ritual":null,"description":"With a touch, you strip off the flesh, muscle, and internal organs off your target, leaving only bare bones. The effect depends on whether the target is a living creature, undead creature, or inanimate corpse. A creature or corpse that lacks flesh, muscle, and internal organs is immune to this spell.\n\nInanimate Corpse The flesh, muscle, viscera, and organs are stripped from the corpse and vanish, leaving only bare bones behind.\n\nLiving Creature Make a spell attack roll. On a hit, the target takes 2d6 slashing damage. On a critical hit, double the damage, and the target also takes 1d4 persistent bleed damage. If this spell's damage kills the target, the corpse is only bones.\n\nUndead Creature Make a spell attack roll. On a hit, the target takes 2d6 slashing damage. On a critical hit, double the damage, and the target also becomes Enfeebled 1 for 1 minute. If this spell's damage destroys the target, only its bare bones remain behind.\n\nHeightened (+1) The slashing damage to living and undead creatures increases by 2d6, and the persistent bleed damage to living creatures increases by 1d4.","source":{"provider":"PAIZO","sourceId":"WV2aMNN9DO5ZBjSv","book":"Pathfinder #186: Ghost King's Rage","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.flourishing-flora","name":"Flourishing Flora","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Plants rapidly grow up from the ground. All creatures in the target area take 2d4 damage. The type of damage depends on the type of plant you choose to grow. On a critical failure, targets experience additional effects, also depending on what you choose to grow. The type of plant and its effects are chosen when you Cast the Spell.\n\n- Cacti Piercing damage, and (@item.level)[bleed] damage on a critical failure.\n\n- Flowers Poison damage, and for 2 rounds on a critical failure.\n\n- Fruits Bludgeoning damage, and Clumsy 1 for 2 rounds on a critical failure.\n\n- Roots Bludgeoning damage, and the affected creatures fall on a critical failure.\n\nHeightened (+1) The damage increases by 1d4, and the persistent bleed damage from cacti increases by 1.","source":{"provider":"PAIZO","sourceId":"b6AQvzs8EotmlK56","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.flurry-of-claws","name":"Flurry of Claws","kind":"SPELL","rank":1,"rarity":"UNCOMMON","traits":["attack","concentrate","focus","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"2 creatures no more than 10 feet from each other","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"JC32rvRkPjO4AK13","formula":"1d8","damageType":"slashing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"JC32rvRkPjO4AK13":"1d8"}},"counteraction":false,"ritual":null,"description":"Vicious dragon claws appear and slash at two nearby foes. Make a spell attack roll against each creature. This counts as two attacks for your multiple attack penalty, but the penalty doesn't increase until you've made both attacks. On a hit, the creatures takes 1d8 slashing plus 1d4 additional damage of a type determined by the magical tradition related to the dragon that influenced your bloodline: arcane force, divine spirit, occult mental, or primal fire.\nHeightened (+1) The initial damage increases by 1d8 and the additional damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"K8vvrOgW4bGakXxm","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.fold-metal","name":"Fold Metal","kind":"SPELL","rank":1,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 unattended metallic object up to 5 Bulk","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bend the target object into a smooth metallic ball no larger than an egg. The target reverts to its original shape only when you Dismiss the spell, the duration expires, or if the ball touches water or fire, whichever comes first.\n\nCreatures that see the reshaped object can attempt a Perception check against your spell DC to notice the ball might not actually be what it seems. If the object is magical, it retains its magical auras but can't be worn, affixed, or Activated.\n\nHeightened (3rd) The spell duration becomes 1 hour.","source":{"provider":"PAIZO","sourceId":"yD819yTgbBFcCh5M","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
